arguments.command:
cat > /app/submit/ftab.c <<'CEOF'
/* Stage usage table for the IPv6 sparse-node codec.
 *
 * Reads a binary request on stdin:
 *     u32 magic, u32 max_stride, u32 n,
 *     then n records of { u8 address[16] (network order), u8 length }.
 * Writes 129*129 little endian u64 values on stdout: F[b][e] is the exact
 * number of bits used by a stage that covers the bit interval (b, e].
 *
 * The layout of a stage depends only on the cut pair (b, e) and the FIB, so
 * the whole table is computed with one bottom-up pass over the prefix trie.
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAGIC 0x31424654u
#define MAXN 300000
#define MAXLEV 129
#define MAXW 4096
#define HSIZE (1u << 20)

typedef struct {
    int32_t parent;
    int32_t child[2];
    int32_t depth;
    uint8_t marked;
} Node;

static Node *nodes;
static int32_t node_count;
static int32_t *htab;
static int32_t *hkey;
static uint32_t hmask = HSIZE - 1;

static uint64_t usage[MAXLEV][MAXLEV];

static uint64_t cntbuf[2][33][MAXW];
static uint64_t livebuf[2][33][MAXW];
static uint64_t mbuf[2][MAXW];

static int32_t *level_nodes;
static int32_t level_start[MAXLEV + 2];
static int32_t level_count[MAXLEV + 2];
static int32_t child_lo[MAXLEV][MAXW];
static int32_t child_hi[MAXLEV][MAXW];

static inline uint64_t align8(uint64_t x) { return (x + 7u) & ~(uint64_t)7u; }
static inline uint64_t align64(uint64_t x) { return (x + 63u) & ~(uint64_t)63u; }

static inline uint32_t hash_key(int32_t key)
{
    uint32_t x = (uint32_t)key * 2654435761u;
    x ^= x >> 15;
    x *= 2246822519u;
    x ^= x >> 13;
    return x & hmask;
}

static int32_t find_or_add(int32_t parent, int bit)
{
    int32_t key = (parent << 1) | bit;
    uint32_t h = hash_key(key);
    while (htab[h]) {
        if (hkey[h] == key)
            return htab[h] - 1;
        h = (h + 1) & hmask;
    }
    int32_t idx = node_count++;
    nodes[idx].parent = parent;
    nodes[idx].depth = nodes[parent].depth + 1;
    nodes[idx].child[0] = nodes[idx].child[1] = -1;
    nodes[idx].marked = 0;
    nodes[parent].child[bit] = idx;
    hkey[h] = key;
    htab[h] = idx + 1;
    return idx;
}

int main(void)
{
    uint32_t magic = 0, max_stride = 0, n = 0;
    if (fread(&magic, 4, 1, stdin) != 1) return 1;
    if (fread(&max_stride, 4, 1, stdin) != 1) return 1;
    if (fread(&n, 4, 1, stdin) != 1) return 1;
    if (magic != MAGIC) return 2;
    if (max_stride < 1 || max_stride > 32) return 3;
    if (n > 2048) return 4;

    nodes = (Node *)calloc(MAXN, sizeof(Node));
    htab = (int32_t *)calloc(HSIZE, sizeof(int32_t));
    hkey = (int32_t *)calloc(HSIZE, sizeof(int32_t));
    level_nodes = (int32_t *)malloc((size_t)MAXN * sizeof(int32_t));
    if (!nodes || !htab || !hkey || !level_nodes) return 5;

    node_count = 1;
    nodes[0].parent = -1;
    nodes[0].depth = 0;
    nodes[0].child[0] = nodes[0].child[1] = -1;
    nodes[0].marked = 0;

    for (uint32_t i = 0; i < n; i++) {
        uint8_t addr[16];
        uint8_t len;
        if (fread(addr, 1, 16, stdin) != 16) return 6;
        if (fread(&len, 1, 1, stdin) != 1) return 6;
        int32_t cur = 0;
        for (int d = 0; d < (int)len; d++) {
            int bit = (addr[d >> 3] >> (7 - (d & 7))) & 1;
            cur = find_or_add(cur, bit);
        }
        nodes[cur].marked = 1;
    }

    /* breadth first levels: children of a node are contiguous and the
     * resulting order is the unsigned network address order */
    int32_t filled = 0;
    level_start[0] = 0;
    level_nodes[filled++] = 0;
    level_count[0] = 1;
    int maxdepth = 0;
    for (int d = 0; d < MAXLEV; d++) {
        int32_t m = level_count[d];
        if (m == 0) break;
        int32_t start = filled;
        for (int32_t j = 0; j < m; j++) {
            int32_t nd = level_nodes[level_start[d] + j];
            int32_t first = filled;
            for (int bit = 0; bit < 2; bit++) {
                int32_t c = nodes[nd].child[bit];
                if (c >= 0) level_nodes[filled++] = c;
            }
            child_lo[d][j] = first;
            child_hi[d][j] = filled;
        }
        level_start[d + 1] = start;
        level_count[d + 1] = filled - start;
        if (filled == start) { maxdepth = d; break; }
        maxdepth = d + 1;
    }

    int cur_buf = 0, next_buf = 1;
    uint64_t *running = (uint64_t *)malloc((size_t)MAXW * sizeof(uint64_t));
    for (int d = maxdepth; d >= 0; d--) {
        int32_t m = level_count[d];
        int kmax = (max_stride <= 128 - d) ? (int)max_stride : 128 - d;
        uint64_t(*cnt)[MAXW] = cntbuf[cur_buf];
        uint64_t(*live)[MAXW] = livebuf[cur_buf];
        uint64_t *totals = mbuf[cur_buf];
        for (int32_t j = 0; j < m; j++)
            cnt[0][j] = nodes[level_nodes[level_start[d] + j]].marked;
        if (d < maxdepth) {
            uint64_t(*cn)[MAXW] = cntbuf[next_buf];
            uint64_t(*ln)[MAXW] = livebuf[next_buf];
            uint64_t *mn = mbuf[next_buf];
            for (int32_t j = 0; j < m; j++) {
                int32_t a0 = child_lo[d][j], a1 = child_hi[d][j];
                uint64_t mm = 0;
                for (int32_t c = a0; c < a1; c++)
                    mm += cn[0][c] + mn[c];
                totals[j] = mm;
                live[0][j] = (mm > 0) ? 1u : 0u;
                for (int k = 1; k <= kmax; k++) {
                    uint64_t s = 0, t = 0;
                    for (int32_t c = a0; c < a1; c++) {
                        s += cn[k - 1][c];
                        t += ln[k - 1][c];
                    }
                    cnt[k][j] = s;
                    live[k][j] = t;
                }
            }
        } else {
            for (int32_t j = 0; j < m; j++) {
                totals[j] = 0;
                live[0][j] = 0;
                for (int k = 1; k <= kmax; k++) { cnt[k][j] = 0; live[k][j] = 0; }
            }
        }
        if (d == 0) {
            for (int t = 1; t <= kmax; t++) {
                uint64_t acc = cnt[0][0] ? 32u : 0u;
                for (int k = 1; k <= t; k++)
                    acc += cnt[k][0] * (32u + align8((uint64_t)k));
                uint64_t h = live[t][0];
                usage[0][t] = align64(128u + acc + h * (32u + align8((uint64_t)t)));
            }
        } else {
            for (int32_t j = 0; j < m; j++) running[j] = 0;
            for (int t = 1; t <= kmax; t++) {
                uint64_t w = 32u + align8((uint64_t)t);
                uint64_t total = 0;
                for (int32_t j = 0; j < m; j++) {
                    running[j] += cnt[t][j] * w;
                    if (live[0][j]) {
                        uint64_t cost = 128u + running[j] + live[t][j] * w;
                        total += align64(cost);
                    }
                }
                usage[d][d + t] = total;
            }
        }
        int tmp = cur_buf; cur_buf = next_buf; next_buf = tmp;
    }

    uint8_t *out = (uint8_t *)malloc((size_t)MAXLEV * MAXLEV * 8);
    for (int b = 0; b < MAXLEV; b++)
        for (int e = 0; e < MAXLEV; e++) {
            uint64_t v = usage[b][e];
            memcpy(out + ((size_t)b * MAXLEV + e) * 8, &v, 8);
        }
    fwrite(out, 1, (size_t)MAXLEV * MAXLEV * 8, stdout);
    fflush(stdout);
    free(out);
    free(running);
    return 0;
}
CEOF
cc -O2 -std=c99 -Wall -Wextra -o /tmp/ftab_test /app/submit/ftab.c && echo "compiled ok"
